    skripta: [
      { naslov: 'Doseljavanje Hrvata', tekst: 'Hrvati su doselili na Balkanski poluotok krajem 6. i u 7. st. (oko 625. g.) iz pradomovine sjeverno od Karpata. Nastanili su se između rijeka Save, Drave i Dunava na sjeveru i Jadranskog mora na jugu. Prostor se dijelio na Primorsku (Dalmaciju) i Panonsku Hrvatsku.' },
      { naslov: 'Knez Trpimir', tekst: 'Knez Trpimir (845.–864.) bio je prvi Trpimirović koji se naslovno nazvao "dux Chroatorum" (knez Hrvata). Poticao je Crkvu — u Rižinicama je osnovao benediktinski samostan. Trpimirova darovnica iz 852. g. jedan je od prvih pisanih dokumenata s imenom "Hrvatska".' },
      { naslov: 'Knez Branimir — međunarodno priznanje', tekst: 'Knez Branimir (879.–892.) dobio je 879. g. papino pismo u kojemu ga papa Ivan VIII. pozdravlja kao nezavisnog kneza. To se smatra prvim međunarodnim crkveno-političkim priznanjem Hrvatske kao samostalne zajednice.' },
      { naslov: 'Kralj Tomislav', tekst: 'Tomislav je 925. g. okrunjen za prvog hrvatskog kralja — papa Ivan X. poslao mu je krunu. Hrvatska je bila moćna: imala je snažnu vojsku i kopnenu vojsku i mornaricu. Na crkvenom saboru u Splitu 925. g. uređeni su crkevni odnosi.' },
      { naslov: 'Petar Krešimir IV. i Zvonimir', tekst: 'Petar Krešimir IV. (1058.–1074.) vladao je "morem i kopnom" — Hrvatska je dostigla najveći teritorijalni opseg. Pripojena su mu dalmatinska primorska mjesta.\n\nDmitar Zvonimir vladao je 1076.–1089. i okrunjen je papinskim blagoslovom. Nakon njegove smrt nastupilo je turbulentno bezvlašće.' },
      { naslov: 'Pacta Conventa i unija s Ugarskom', tekst: 'Godine 1102. hrvatska vlastela sklopila je sporazum Pacta Conventa s ugarskim kraljem Kolomanom. Hrvatska je zadržala svoja prava i upravu (sabor, ban), ali je ušla u personalnu uniju s Ugarskom. Ovaj sporazum oblikovao je hrvatsku povijest sve do 1918. g.' },
    ],
